/* ============================================
   CommerceForge Dev Docs — Design System
   Dark-mode-first | Glassmorphism | Minimal
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2128;
  --bg-elevated: #21262d;
  --border: #30363d;
  --border-light: rgba(48, 54, 61, 0.6);
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-tertiary: #6e7681;
  --accent-green: #3bf0c0;
  --accent-green-dim: rgba(59, 240, 192, 0.15);
  --accent-blue: #6e8fc8;
  --accent-blue-dim: rgba(110, 143, 200, 0.15);
  --cta-hover: #2dd4a8;
  --code-bg: #0d1117;
  --glass-bg: rgba(22, 27, 34, 0.7);
  --glass-border: rgba(48, 54, 61, 0.6);
  --glass-glow: rgba(59, 240, 192, 0.08);
  --sidebar-width: 260px;
  --sidebar-collapsed: 0px;
  --nav-height: 64px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --transition-fast: 150ms ease;
  --transition-med: 250ms ease;
  --transition-slow: 350ms ease-out;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'SF Mono', Consolas, monospace;
  --max-width: 1280px;
}

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  font-size: 16px;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--accent-green); }
a:focus-visible { outline: 2px solid var(--accent-green); outline-offset: 2px; border-radius: 2px; }

img { max-width: 100%; display: block; }

/* --- Typography --- */
h1, h2, h3, h4 { color: var(--text-primary); line-height: 1.25; font-weight: 600; letter-spacing: -0.02em; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); font-weight: 700; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2rem); margin-bottom: 0.75em; }
h3 { font-size: 1.125rem; margin-bottom: 0.5em; }
p { color: var(--text-secondary); max-width: 70ch; }
.text-lg { font-size: 1.125rem; line-height: 1.7; }
.text-sm { font-size: 0.875rem; }
.mono { font-family: var(--font-mono); }

/* --- Container --- */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.container-narrow { max-width: 960px; margin: 0 auto; padding: 0 24px; }

/* --- Navigation --- */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.nav-logo {
  display: flex; align-items: center; gap: 10px;
  font-weight: 700; font-size: 1.125rem; color: var(--text-primary);
  white-space: nowrap;
}
.nav-logo svg { flex-shrink: 0; }
.nav-logo:hover { color: var(--text-primary); }
.nav-links { display: flex; align-items: center; gap: 4px; }
.nav-links a {
  padding: 8px 14px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: color var(--transition-fast), background var(--transition-fast);
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.nav-links a.active { color: var(--accent-green); }
.nav-utility { display: flex; align-items: center; gap: 8px; }
.nav-search-btn {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: var(--radius-sm);
  background: var(--bg-tertiary); border: 1px solid var(--border);
  color: var(--text-tertiary); font-size: 0.85rem; cursor: pointer;
  transition: border-color var(--transition-fast), color var(--transition-fast);
}
.nav-search-btn:hover { border-color: var(--accent-green); color: var(--text-secondary); }
.nav-search-btn kbd {
  font-family: var(--font-sans); font-size: 0.75rem;
  padding: 1px 5px; border-radius: 3px;
  background: var(--bg-elevated); border: 1px solid var(--border);
  color: var(--text-tertiary); margin-left: 8px;
}
.theme-toggle {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: none; border: 1px solid var(--border); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary); transition: color var(--transition-fast), border-color var(--transition-fast);
}
.theme-toggle:hover { color: var(--accent-green); border-color: var(--accent-green); }
.login-btn {
  padding: 7px 16px; border-radius: var(--radius-sm);
  font-size: 0.875rem; font-weight: 500; cursor: pointer;
  background: transparent; border: 1px solid var(--border);
  color: var(--text-secondary); transition: all var(--transition-fast);
}
.login-btn:hover { border-color: var(--accent-green); color: var(--accent-green); }

.mobile-menu-btn {
  display: none; width: 40px; height: 40px; background: none; border: none;
  color: var(--text-secondary); cursor: pointer; align-items: center; justify-content: center;
}
.mobile-menu { display: none; }

/* --- Hero --- */
.hero {
  padding: 140px 0 80px;
  text-align: center;
}
.hero h1 { margin-bottom: 20px; }
.hero h1 span { color: var(--accent-green); }
.hero-subtitle {
  font-size: 1.125rem; color: var(--text-secondary);
  max-width: 640px; margin: 0 auto 36px; line-height: 1.7;
}
.hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* --- Buttons --- */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 10px 22px; border-radius: var(--radius-sm);
  font-size: 0.9rem; font-weight: 500; cursor: pointer;
  transition: all var(--transition-fast); border: none;
  text-decoration: none; white-space: nowrap;
}
.btn-primary {
  background: var(--accent-green); color: #0d1117;
}
.btn-primary:hover { background: var(--cta-hover); color: #0d1117; }
.btn-secondary {
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn-secondary:hover { border-color: var(--accent-green); color: var(--accent-green); }
.btn-ghost {
  background: transparent; color: var(--accent-green);
  padding: 8px 0;
}
.btn-ghost:hover { color: var(--cta-hover); }
.btn svg { flex-shrink: 0; }

/* --- Glass Cards --- */
.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: border-color var(--transition-med), transform var(--transition-med), box-shadow var(--transition-med);
}
.glass-card:hover {
  border-color: rgba(59, 240, 192, 0.25);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(59, 240, 192, 0.06);
}
.glass-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--accent-green-dim);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; color: var(--accent-green);
}
.glass-card h3 { margin-bottom: 10px; }
.glass-card p { font-size: 0.9rem; margin-bottom: 16px; }

/* --- Product Cards Grid --- */
.product-cards {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 24px; padding: 80px 0;
}
@media (max-width: 900px) { .product-cards { grid-template-columns: 1fr; } }

/* --- CLI Section --- */
.cli-section { padding: 80px 0; }
.cli-section h2 { text-align: center; }
.cli-section .section-subtitle {
  text-align: center; max-width: 640px; margin: 0 auto 40px;
  color: var(--text-secondary); font-size: 1rem; line-height: 1.7;
}

/* Accordion */
.accordion { border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }
.accordion-header {
  width: 100%; padding: 20px 24px;
  background: var(--bg-secondary); border: none;
  color: var(--text-primary); font-size: 1rem; font-weight: 500;
  cursor: pointer; display: flex; align-items: center; justify-content: space-between;
  transition: background var(--transition-fast);
  font-family: var(--font-sans);
}
.accordion-header:hover { background: var(--bg-tertiary); }
.accordion-header:focus-visible { outline: 2px solid var(--accent-green); outline-offset: -2px; }
.accordion-chevron {
  transition: transform var(--transition-med);
  color: var(--text-secondary); flex-shrink: 0;
}
.accordion-item.active .accordion-chevron { transform: rotate(180deg); }
.accordion-content {
  max-height: 0; overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
  background: var(--bg-secondary);
}
.accordion-item.active .accordion-content { max-height: 600px; }
.accordion-body { padding: 0 24px 24px; }

/* Tabs */
.tabs { display: flex; gap: 0; border-bottom: 1px solid var(--border); margin-bottom: 0; }
.tab-btn {
  padding: 10px 20px; background: none; border: none;
  color: var(--text-secondary); font-size: 0.85rem; font-weight: 500;
  cursor: pointer; border-bottom: 2px solid transparent;
  transition: color var(--transition-fast), border-color var(--transition-fast);
  font-family: var(--font-sans);
  margin-bottom: -1px;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { color: var(--accent-green); border-bottom-color: var(--accent-green); }
.tab-btn:focus-visible { outline: 2px solid var(--accent-green); outline-offset: 2px; }
.code-block {
  background: var(--bg-primary); border: 1px solid var(--border);
  border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md);
  padding: 20px; overflow-x: auto;
}
.code-block pre {
  font-family: var(--font-mono); font-size: 0.875rem;
  line-height: 1.7; color: var(--text-primary);
  margin: 0; white-space: pre;
}
.code-block .comment { color: var(--text-tertiary); }
.code-block .cmd { color: var(--accent-green); }

/* Step list */
.step-list { list-style: none; margin: 16px 0; }
.step-list li {
  padding: 10px 0; color: var(--text-secondary);
  font-size: 0.9rem; display: flex; gap: 12px; align-items: flex-start;
}
.step-list li .step-num {
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--accent-green-dim); color: var(--accent-green);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 600; flex-shrink: 0;
}

/* --- Launch CTA --- */
.launch-section { padding: 80px 0; }
.launch-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
@media (max-width: 768px) { .launch-cards { grid-template-columns: 1fr; } }

/* --- Community --- */
.community-section { padding: 80px 0; }
.community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
@media (max-width: 900px) { .community-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .community-grid { grid-template-columns: 1fr; } }

.community-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  transition: border-color var(--transition-med), transform var(--transition-med);
}
.community-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); }
.community-card h3 { font-size: 0.95rem; margin-bottom: 8px; }
.community-card p { font-size: 0.85rem; }
.community-card a { color: var(--accent-blue); font-size: 0.85rem; font-weight: 500; }
.community-card a:hover { color: var(--accent-green); }

/* --- Sidebar Layout --- */
.page-layout { display: flex; min-height: calc(100vh - var(--nav-height)); padding-top: var(--nav-height); }
.sidebar {
  width: var(--sidebar-width); min-width: var(--sidebar-width);
  border-right: 1px solid var(--border);
  padding: 24px 0; position: sticky; top: var(--nav-height);
  height: calc(100vh - var(--nav-height)); overflow-y: auto;
  transition: width var(--transition-med), min-width var(--transition-med), padding var(--transition-med);
  background: var(--bg-primary);
}
.sidebar.collapsed { width: 0; min-width: 0; padding: 24px 0; overflow: hidden; }
.sidebar-toggle {
  position: absolute; top: 28px; right: -14px;
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--bg-secondary); border: 1px solid var(--border);
  color: var(--text-secondary); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition-fast); z-index: 5;
}
.sidebar-toggle:hover { border-color: var(--accent-green); color: var(--accent-green); }
.sidebar-nav { padding: 0 16px; }
.sidebar-nav a {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 0.875rem;
  transition: all var(--transition-fast); white-space: nowrap;
}
.sidebar-nav a:hover { color: var(--text-primary); background: var(--bg-secondary); }
.sidebar-nav a.active { color: var(--accent-green); background: var(--accent-green-dim); }
.main-content {
  flex: 1; min-width: 0; padding: 40px 48px 80px;
}
@media (max-width: 900px) {
  .sidebar { position: fixed; left: 0; z-index: 90; transform: translateX(-100%); width: 260px; min-width: 260px; }
  .sidebar.mobile-open { transform: translateX(0); box-shadow: 4px 0 24px rgba(0,0,0,0.5); }
  .sidebar.collapsed { transform: translateX(-100%); }
  .sidebar-toggle { display: none; }
  .mobile-sidebar-btn { display: flex !important; }
  .main-content { padding: 24px 16px 60px; }
}

.mobile-sidebar-btn {
  display: none; align-items: center; gap: 6px;
  padding: 8px 14px; border-radius: var(--radius-sm);
  background: var(--bg-secondary); border: 1px solid var(--border);
  color: var(--text-secondary); font-size: 0.85rem; cursor: pointer;
  margin-bottom: 20px;
}

/* --- Section spacing for interior pages --- */
.doc-section { margin-bottom: 64px; }
.doc-section h2 { margin-bottom: 16px; }
.doc-section > p { margin-bottom: 24px; }

/* --- Grid layouts --- */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
@media (max-width: 900px) {
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .grid-6 { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 520px) {
  .grid-3, .grid-6 { grid-template-columns: 1fr; }
}

/* --- Protocol Diagram --- */
.protocol-diagram {
  display: flex; justify-content: center; align-items: center;
  gap: 40px; padding: 40px 0; flex-wrap: wrap;
}
.protocol-actor {
  text-align: center; padding: 24px 32px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md); min-width: 140px;
}
.protocol-actor .actor-name { font-weight: 600; color: var(--accent-green); font-size: 0.95rem; margin-bottom: 4px; }
.protocol-actor .actor-desc { font-size: 0.8rem; color: var(--text-secondary); }
.protocol-arrow { color: var(--text-tertiary); font-size: 1.5rem; }
@media (max-width: 768px) {
  .protocol-diagram { flex-direction: column; gap: 16px; }
  .protocol-arrow { transform: rotate(90deg); }
}

/* --- Badge --- */
.badge {
  display: inline-block; padding: 3px 10px;
  border-radius: 12px; font-size: 0.75rem; font-weight: 500;
  background: rgba(255, 166, 0, 0.15); color: #ffa600;
  border: 1px solid rgba(255, 166, 0, 0.3);
}

/* --- How It Works Cards --- */
.how-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
@media (max-width: 768px) { .how-cards { grid-template-columns: 1fr; } }
.how-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 32px;
}
.how-card .how-icon {
  width: 40px; height: 40px; border-radius: var(--radius-sm);
  background: var(--accent-green-dim); color: var(--accent-green);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}
.how-card h3 { margin-bottom: 8px; }

/* --- Support Cards --- */
.support-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
@media (max-width: 900px) { .support-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .support-grid { grid-template-columns: 1fr; } }
.support-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px; text-align: center;
  transition: border-color var(--transition-med);
}
.support-card:hover { border-color: var(--accent-blue); }
.support-card h3 { font-size: 0.95rem; margin-bottom: 8px; }
.support-card p { font-size: 0.8rem; }

/* --- Footer --- */
.footer {
  border-top: 1px solid var(--border);
  padding: 48px 0 32px; margin-top: 40px;
}
.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px; margin-bottom: 40px;
}
@media (max-width: 900px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .footer-grid { grid-template-columns: 1fr; } }
.footer-col h4 {
  font-size: 0.8rem; font-weight: 600; color: var(--text-primary);
  text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 14px;
}
.footer-col a {
  display: block; color: var(--text-secondary); font-size: 0.85rem;
  padding: 4px 0; transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--accent-green); }
.footer-bottom {
  border-top: 1px solid var(--border); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  color: var(--text-tertiary); font-size: 0.8rem;
}

/* --- Best Practices list --- */
.bp-list { list-style: none; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
@media (max-width: 768px) { .bp-list { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 520px) { .bp-list { grid-template-columns: 1fr; } }
.bp-item {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 16px; background: var(--bg-secondary);
  border: 1px solid var(--border); border-radius: var(--radius-md);
}
.bp-item .bp-icon { color: var(--accent-green); flex-shrink: 0; margin-top: 2px; }
.bp-item .bp-text { font-size: 0.9rem; color: var(--text-secondary); }
.bp-item .bp-text strong { color: var(--text-primary); display: block; margin-bottom: 2px; }

/* --- Theming highlights --- */
.theme-highlights { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
@media (max-width: 768px) { .theme-highlights { grid-template-columns: 1fr; } }
.theme-highlight-item {
  display: flex; gap: 16px; padding: 24px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
.theme-highlight-item .th-icon { color: var(--accent-green); flex-shrink: 0; margin-top: 2px; }
.theme-highlight-item h3 { font-size: 0.95rem; margin-bottom: 4px; }
.theme-highlight-item p { font-size: 0.85rem; }

/* --- Theme sub-sections --- */
.theme-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; margin-bottom: 32px; }
@media (max-width: 768px) { .theme-cards { grid-template-columns: 1fr; } }
.theme-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  transition: border-color var(--transition-med);
}
.theme-card:hover { border-color: rgba(59, 240, 192, 0.3); }
.theme-card h3 { font-size: 0.95rem; margin-bottom: 6px; }
.theme-card p { font-size: 0.85rem; }

/* --- Mobile responsive nav --- */
@media (max-width: 900px) {
  .nav-links { display: none; }
  .nav-utility .login-btn { display: none; }
  .mobile-menu-btn { display: flex; }
  .mobile-menu.open {
    display: flex; flex-direction: column; position: fixed;
    top: var(--nav-height); left: 0; right: 0; bottom: 0;
    background: var(--bg-primary); padding: 24px; z-index: 99;
    border-top: 1px solid var(--border);
  }
  .mobile-menu.open a {
    padding: 14px 0; color: var(--text-secondary); font-size: 1rem;
    border-bottom: 1px solid var(--border);
  }
  .mobile-menu.open a:hover { color: var(--accent-green); }
}

/* --- Page-specific hero (smaller) --- */
.page-hero {
  padding: 48px 0 36px; border-bottom: 1px solid var(--border); margin-bottom: 48px;
}
.page-hero h1 { font-size: clamp(1.5rem, 3vw, 2.25rem); margin-bottom: 12px; }
.page-hero p { max-width: 600px; }

/* --- Headless dev tools --- */
.dev-tools-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
@media (max-width: 768px) { .dev-tools-grid { grid-template-columns: 1fr; } }
.dev-tool-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 28px;
}
.dev-tool-card h3 { font-size: 1rem; margin-bottom: 8px; color: var(--accent-green); }
.dev-tool-card p { font-size: 0.875rem; }

/* --- Checkout flow --- */
.checkout-flow {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 40px;
  text-align: center;
}
.checkout-flow h3 { margin-bottom: 8px; }
.checkout-flow p { max-width: 540px; margin: 0 auto 16px; }

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--bg-elevated); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--border); }

/* --- Reduced motion --- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
  html { scroll-behavior: auto; }
}

